    adcs_vec3_t norm_ref_a, norm_ref_b;
    adcs_vec3_t cross;
    double sin_sep;
    double selected_variance;
    adcs_status_t status;

    if ((body_a == NULL) || (body_b == NULL) || (ref_a == NULL) || (ref_b == NULL) ||
        (variance_a == NULL) || (variance_b == NULL) || (primary_index == NULL) ||
        (geometry_quality == NULL) || (c_bi == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(*variance_a) || (*variance_a <= 0.0) || !isfinite(*variance_b) || (*variance_b <= 0.0)) {
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(ref_a, ADCS_EPS_NORM, &norm_ref_a) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    if (adcs_vec3_normalize(ref_b, ADCS_EPS_NORM, &norm_ref_b) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    cross = adcs_vec3_cross(&norm_ref_a, &norm_ref_b);
    sin_sep = adcs_vec3_norm(&cross);

    if (sin_sep <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    if (*variance_a <= *variance_b) {
        *primary_index = 0;
        selected_variance = *variance_a;
        status = adcs_triad(body_a, body_b, ref_a, ref_b, c_bi);
    } else {
        *primary_index = 1;
        selected_variance = *variance_b;
        status = adcs_triad(body_b, body_a, ref_b, ref_a, c_bi);
    }

    if (status != ADCS_OK) {
        return status;
    }

    *geometry_quality = sin_sep / selected_variance;

    return ADCS_OK;
}

